sql_query:
SELECT "Type of combination"
FROM clinical_trials
WHERE "Included in MA" = 'Yes' AND "Monotherapy/combination" = 'Combination' AND "Name of ICI" = 'Ipilimumab' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Type of combination" AS source_value FROM clinical_trials WHERE "Included in MA" = 'Yes' AND "Monotherapy/combination" = 'Combination' AND "Name of ICI" = 'Ipilimumab' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_combo_type_norm(source_value) AS "combo_type_norm"
FROM base;
